import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem122 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["Pcye5MBHzWVlBIhtSnXX","Kit 10 Pote De Vidro Marmita Hermético 640ml Freezer Fitness Borossilicato 4 Travas Micro-ondas Azul-Escuro","Kit com 10 potes de vidro — 640 mL anunciados por unidade","https://www.mercadolivre.com.br/p/MLB55829716?pdp_filters=item_id%3AMLB5724593344"],["PdIYZ9X5RhTbhmKJyZRw","Perfume Vodka Brasil Amarelo Paris Elysees Masculino Intense 100ml","Paris Elysees Vodka Brasil Amarelo — 100 mL anunciados","https://www.mercadolivre.com.br/p/MLB18948403?pdp_filters=item_id%3AMLB2629291215"],["Ped2JwDkTqMRNcZ0BhTf","Skatenete Max Led Ajustável Patinete 120kg Bandeirante","Patinete Bandeirante Skatenete Max LED ajustável","https://produto.mercadolivre.com.br/MLB-3894608627-skatenete-max-led-ajustavel-patinete-120kg-bandeirante-_JM"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
